  // pastda progress chizig'i
  ekran.drawRect(0, 50, 128, 10, SSD1306_WHITE);
  ekran.fillRect(0, 50, map(qiymat, 0, 50, 0, 128), 10, SSD1306_WHITE);

  ekran.display();          // ENG MUHIM QATOR — usiz ekran bo'sh qoladi

  qiymat = (qiymat + 1) % 51;
  delay(200);
}

